'use client'

import type { ComponentProps } from 'react'
import {
  Accordion as UiAccordion,
  AccordionHeader as UiAccordionHeader,
  AccordionItem as UiAccordionItem,
  AccordionPanel as UiAccordionPanel,
  AccordionTrigger as UiAccordionTrigger,
} from '@ui-sdk/react/accordion'

import './accordion.css'

function omit<T extends object, const K extends readonly (keyof T)[]>(
  obj: T,
  ...keys: K
): Omit<T, K[number]> {
  const copy = { ...obj }
  for (const key of keys) delete copy[key]
  return copy
}

/**
 * Accordion, a 1:1 port of opencode's Accordion (`@opencode/ui`, MIT):
 * `packages/ui/src/data-display/accordion` (`accordion.css`), on top of
 * ui-sdk's headless Accordion, AccordionItem, AccordionHeader,
 * AccordionTrigger and AccordionPanel.
 *
 * Styling lives in `accordion.css` as attribute rules (`data-open`,
 * `data-disabled`), copied from upstream, so the stacked frame, the hover
 * fill, the open panel's border and fill, the first/last corner radii and
 * the disabled cursor match. Behaviour (open state, one or many items,
 * keyboard, ARIA wiring, panel mounting) comes from `@ui-sdk/react`.
 *
 * Upstream is Kobalte based, so its `data-expanded` and
 * `data-slot="accordion-content"` become ui-sdk's `data-open` and
 * `data-slot="accordion-panel"`. Its trigger is unstyled when focused and
 * ui-sdk keeps that: a disabled or open trigger stays focusable, and a
 * panel takes its padding from its content, like upstream.
 */

type UiAccordionProps = ComponentProps<typeof UiAccordion>

export type AccordionProps = Omit<UiAccordionProps, 'className' | 'render'> & {
  className?: UiAccordionProps['className']
  render?: UiAccordionProps['render']
}

export function Accordion(props: AccordionProps) {
  const rest = omit(props, 'className', 'render')

  return <UiAccordion {...rest} className={props.className} render={props.render} />
}

type UiAccordionItemProps = ComponentProps<typeof UiAccordionItem>

export type AccordionItemProps = Omit<
  UiAccordionItemProps,
  'className' | 'render'
> & {
  className?: UiAccordionItemProps['className']
  render?: UiAccordionItemProps['render']
}

export function AccordionItem(props: AccordionItemProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiAccordionItem {...rest} className={props.className} render={props.render} />
  )
}

type UiAccordionHeaderProps = ComponentProps<typeof UiAccordionHeader>

export type AccordionHeaderProps = Omit<
  UiAccordionHeaderProps,
  'className' | 'render'
> & {
  className?: UiAccordionHeaderProps['className']
  render?: UiAccordionHeaderProps['render']
}

export function AccordionHeader(props: AccordionHeaderProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiAccordionHeader {...rest} className={props.className} render={props.render} />
  )
}

type UiAccordionTriggerProps = ComponentProps<typeof UiAccordionTrigger>

export type AccordionTriggerProps = Omit<
  UiAccordionTriggerProps,
  'className' | 'render'
> & {
  className?: UiAccordionTriggerProps['className']
  render?: UiAccordionTriggerProps['render']
}

export function AccordionTrigger(props: AccordionTriggerProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiAccordionTrigger {...rest} className={props.className} render={props.render} />
  )
}

type UiAccordionPanelProps = ComponentProps<typeof UiAccordionPanel>

export type AccordionPanelProps = Omit<
  UiAccordionPanelProps,
  'className' | 'render'
> & {
  className?: UiAccordionPanelProps['className']
  render?: UiAccordionPanelProps['render']
}

export function AccordionPanel(props: AccordionPanelProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiAccordionPanel {...rest} className={props.className} render={props.render} />
  )
}

/*
 * 1:1 port of opencode's Accordion (`@opencode/ui`, MIT):
 * packages/ui/src/data-display/accordion/accordion.css.
 *
 * Only the selectors changed, to meet ui-sdk's markup. Every value is
 * upstream, so rest / hover / open / focus-visible / disabled match
 * `data-component="accordion"`:
 *
 *   [data-component="accordion"]        →  [data-slot="accordion"]
 *   [data-slot="accordion-item"]        →  same (ui-sdk's item slot)
 *   [data-slot="accordion-header"]      →  same (ui-sdk's header slot)
 *   [data-slot="accordion-trigger"]     →  same (ui-sdk's trigger slot)
 *   [data-slot="accordion-content"]     →  [data-slot="accordion-panel"]
 *   [data-expanded]                     →  [data-open]
 *   [data-disabled]                     →  same (ui-sdk's attribute)
 *
 * Upstream nests the item rules under the root, so they stay scoped to the
 * root here too. Its `@keyframes slideDown / slideUp` read Kobalte's
 * `--kb-accordion-content-height` and no rule in the file ever applies them,
 * so they are not carried over; ui-sdk exposes `--accordion-panel-height` for
 * a panel animation instead.
 *
 * accordion.css has no [data-color-scheme="dark"] block: the --v2-* tokens
 * flip with the scheme. The trigger drops its focus ring upstream, so
 * `:focus-visible { outline: none }` is kept as is.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@layer components {
  [data-slot="accordion"] {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0px;
    align-self: stretch;
  }

  [data-slot="accordion"] [data-slot="accordion-item"] {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    align-self: stretch;
    overflow: visible;
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]
    + [data-slot="accordion-item"] {
    margin-top: -1px;
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]
    [data-slot="accordion-header"] {
    width: 100%;
    display: flex;
    align-items: center;
    margin: 0;
    padding: 0;
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]
    [data-slot="accordion-header"]
    [data-slot="accordion-trigger"] {
    width: 100%;
    display: flex;
    height: 32px;
    padding: 8px 12px;
    justify-content: space-between;
    align-items: center;
    align-self: stretch;
    cursor: default;
    user-select: none;

    background-color: var(--v2-background-bg-base);
    border: 1px solid var(--v2-border-border-base);
    border-radius: 0;
    box-shadow: none;
    overflow: clip;
    color: var(--v2-text-text-base);
    transition: background-color 0.15s ease;

    font-family: var(--font-family-sans);
    font-size: var(--font-size-small);
    font-style: normal;
    font-weight: var(--font-weight-regular);
    line-height: var(--line-height-large);
    letter-spacing: var(--letter-spacing-normal);
  }

  @media (hover: hover) {
    [data-slot="accordion"]
      [data-slot="accordion-item"]
      [data-slot="accordion-header"]
      [data-slot="accordion-trigger"]:hover:not([data-disabled]) {
      background-color: var(--v2-overlay-simple-overlay-hover);
    }
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]
    [data-slot="accordion-header"]
    [data-slot="accordion-trigger"]:focus-visible {
    outline: none;
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]
    [data-slot="accordion-header"]
    [data-slot="accordion-trigger"][data-disabled] {
    cursor: not-allowed;
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]:first-child
    [data-slot="accordion-header"]
    [data-slot="accordion-trigger"] {
    border-top-left-radius: var(--radius-lg);
    border-top-right-radius: var(--radius-lg);
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]:last-child:not([data-open])
    [data-slot="accordion-header"]
    [data-slot="accordion-trigger"] {
    border-bottom-left-radius: var(--radius-lg);
    border-bottom-right-radius: var(--radius-lg);
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"][data-open]
    [data-slot="accordion-panel"] {
    border: 1px solid var(--v2-border-border-base);
    border-top: 0;
    background-color: var(--v2-background-bg-layer-01);
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]:last-child[data-open]
    [data-slot="accordion-panel"] {
    border-bottom-left-radius: var(--radius-lg);
    border-bottom-right-radius: var(--radius-lg);
  }

  [data-slot="accordion"]
    [data-slot="accordion-item"]
    [data-slot="accordion-panel"] {
    overflow: hidden;
    width: 100%;
    border: 0;
    background-color: transparent;
  }
}
